func TestTraceTextRules(t *testing.T) {
	tests := []struct {
		name  string
		data  []byte
		steps []string
		err   string
	}{
		{name: "BOM skips CRLF and unterminated final line", data: []byte("\ufeff# header\n\n  \t\n{\"tool\":\"x\"}\r\n# note\n{\"tool\":\"y\"}"), steps: []string{"x", "y"}},
		{name: "empty", data: []byte{}, steps: []string{}},
		{name: "indented comment is JSON", data: []byte(" # note\n"), err: "t.jsonl:1: invalid JSON"},
		{name: "unicode space is not skipped", data: []byte("\u00a0\n"), err: "t.jsonl:1: invalid JSON"},
		{name: "form feed is not skipped", data: []byte("\f\n"), err: "t.jsonl:1: invalid JSON"},
		{name: "only one BOM is removed", data: []byte("\ufeff\ufeff{\"tool\":\"x\"}"), err: "t.jsonl:1: invalid JSON"},
		{name: "physical lines", data: []byte("# c\n\n{\"tool\":\"ok\"}\n   \n{\n"), err: "t.jsonl:5: invalid JSON"},
		{name: "UTF-8 checked before syntax", data: []byte("{\n\xff"), err: "t.jsonl: input is not valid UTF-8"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			calls, err := trace.Parse(tc.data, "t.jsonl")
			if tc.err != "" {
				if err == nil || err.Error() != tc.err || calls != nil {
					t.Fatalf("Parse = (%#v, %v), want (nil, %q)", calls, err, tc.err)
				}
				return
			}
			if err != nil || len(calls) != len(tc.steps) {
				t.Fatalf("Parse = (%#v, %v), want %d calls", calls, err, len(tc.steps))
			}
			for i, tool := range tc.steps {
				if calls[i].Step != i+1 || calls[i].Tool != tool {
					t.Errorf("call %d = %#v, want step %d tool %q", i, calls[i], i+1, tool)
				}
			}
		})
	}
}

func TestTraceSchema(t *testing.T) {
	tests := []struct {
		input string
		want  trace.Call
		err   string
	}{
		{input: "{\"tool\":\"x\"}", want: trace.Call{Step: 1, Tool: "x", Args: "{}", OK: true}},
		{input: "{\"tool\":\"a:b-c_d\",\"args\":{\"b\":[],\"a\":{}},\"ok\":false,\"tokens\":1000000000,\"note\":null}", want: trace.Call{Step: 1, Tool: "a:b-c_d", Args: "{\"a\":{},\"b\":[]}", Tokens: 1000000000}},
		{input: "{\"tool\":\"x\",\"tokens\":-0}", want: trace.Call{Step: 1, Tool: "x", Args: "{}", OK: true}},
		{input: "[]", err: "t.jsonl:1: not a JSON object"},
		{input: "null", err: "t.jsonl:1: not a JSON object"},
		{input: "5", err: "t.jsonl:1: not a JSON object"},
		{input: "\"s\"", err: "t.jsonl:1: not a JSON object"},
		{input: "[1]", err: "t.jsonl:1: not a JSON object"},
		{input: "{}", err: "t.jsonl:1: missing \"tool\""},
		{input: "{\"tool\":1}", err: "t.jsonl:1: \"tool\" must be 1 to 64 characters of A-Z a-z 0-9 _ . : -"},
		{input: "{\"tool\":\"\"}", err: "t.jsonl:1: \"tool\" must be 1 to 64 characters of A-Z a-z 0-9 _ . : -"},
		{input: "{\"tool\":\"a b\"}", err: "t.jsonl:1: \"tool\" must be 1 to 64 characters of A-Z a-z 0-9 _ . : -"},
		{input: "{\"tool\":\"x\",\"args\":[]}", err: "t.jsonl:1: \"args\" must be an object"},
		{input: "{\"tool\":\"x\",\"args\":null}", err: "t.jsonl:1: \"args\" must be an object"},
		{input: "{\"tool\":\"x\",\"ok\":null}", err: "t.jsonl:1: \"ok\" must be true or false"},
		{input: "{\"tool\":\"x\",\"ok\":1}", err: "t.jsonl:1: \"ok\" must be true or false"},
		{input: "{\"tool\":\"x\",\"ok\":\"true\"}", err: "t.jsonl:1: \"ok\" must be true or false"},
		{input: "{\"tool\":\"x\",\"tokens\":-1}", err: "t.jsonl:1: \"tokens\" must be an integer from 0 to 1000000000"},
		{input: "{\"tool\":\"x\",\"tokens\":1000000001}", err: "t.jsonl:1: \"tokens\" must be an integer from 0 to 1000000000"},
		{input: "{\"tool\":\"x\",\"tokens\":\"5\"}", err: "t.jsonl:1: \"tokens\" must be an integer from 0 to 1000000000"},
		{input: "{\"tool\":\"x\",\"tokens\":123456789012345678901234567890}", err: "t.jsonl:1: \"tokens\" must be an integer from 0 to 1000000000"},
		{input: "{\"tool\":\"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.\"}", want: trace.Call{Step: 1, Tool: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.", Args: "{}", OK: true}},
		{input: "{\"tool\":\"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.a\"}", err: "t.jsonl:1: \"tool\" must be 1 to 64 characters of A-Z a-z 0-9 _ . : -"},
	}
	for _, tc := range tests {
		calls, err := trace.Parse([]byte(tc.input), "t.jsonl")
		if tc.err != "" {
			if err == nil || err.Error() != tc.err || calls != nil {
				t.Errorf("%s: Parse = (%#v, %v), want nil, %q", tc.input, calls, err, tc.err)
			}
		} else if err != nil || len(calls) != 1 || calls[0] != tc.want {
			t.Errorf("%s: Parse = (%#v, %v), want %#v", tc.input, calls, err, tc.want)
		}
	}
	calls, err := trace.Parse([]byte("{\"tool\":\"é\"}"), "t.jsonl")
	if err == nil || calls != nil {
		t.Errorf("non-ASCII tool accepted: (%#v, %v)", calls, err)
	}
}

func TestTraceToolLengthBoundaryAssertions(t *testing.T) {
	calls, err := trace.Parse([]byte("{\"tool\":\"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.\"}"), "t.jsonl")
	if err != nil || len(calls) != 1 || calls[0].Tool != "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_." {
		t.Errorf("64-character tool = (%#v, %v), want one call with the literal 64-character tool", calls, err)
	}

	calls, err = trace.Parse([]byte("{\"tool\":\"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.a\"}"), "t.jsonl")
	if err == nil || err.Error() != "t.jsonl:1: \"tool\" must be 1 to 64 characters of A-Z a-z 0-9 _ . : -" || calls != nil {
		t.Errorf("65-character tool = (%#v, %v), want exact length error and nil calls", calls, err)
	}

	calls, err = trace.Parse([]byte("{\"tool\":\"\"}"), "t.jsonl")
	if err == nil || err.Error() != "t.jsonl:1: \"tool\" must be 1 to 64 characters of A-Z a-z 0-9 _ . : -" || calls != nil {
		t.Errorf("empty tool = (%#v, %v), want exact length error and nil calls", calls, err)
	}
}

func TestTraceValidationOrder(t *testing.T) {
	tests := []struct{ input, want string }{
		{"{\"tool\":1,\"note\":1.5}", "t.jsonl:1: number must be an integer"},
		{"{\"tool\":\"x\",\"note\":{\"a\":1.5,\"a\":2}}", "t.jsonl:1: number must be an integer"},
		{"{\"tokens\":-1,\"ok\":null,\"args\":[]}", "t.jsonl:1: missing \"tool\""},
		{"{\"tokens\":-1,\"ok\":null,\"args\":[],\"tool\":1}", "t.jsonl:1: \"tool\" must be 1 to 64 characters of A-Z a-z 0-9 _ . : -"},
		{"{\"tokens\":-1,\"ok\":null,\"args\":[],\"tool\":\"x\"}", "t.jsonl:1: \"args\" must be an object"},
		{"{\"tokens\":-1,\"ok\":null,\"tool\":\"x\"}", "t.jsonl:1: \"ok\" must be true or false"},
		{"{\"tool\":\"x\",\"tokens\":1.0}", "t.jsonl:1: number must be an integer"},
		{"{\"tool\":\"x\",\"unknown\":true}", ""},
	}
	for _, tc := range tests {
		calls, err := trace.Parse([]byte(tc.input), "t.jsonl")
		if tc.want == "" {
			if err != nil || len(calls) != 1 {
				t.Errorf("%s: Parse = (%#v, %v), want success", tc.input, calls, err)
			}
		} else if err == nil || err.Error() != tc.want || calls != nil {
			t.Errorf("%s: Parse = (%#v, %v), want nil, %q", tc.input, calls, err, tc.want)
		}
	}
}

func TestCallIdentity(t *testing.T) {
	calls, err := trace.Parse([]byte("{\"tool\":\"read_file\",\"args\":{\"z\":0,\"a\":1}}\n{\"tool\":\"read_file\",\"args\":{\"a\":1,\"z\":-0}}"), "t.jsonl")
	if err != nil || len(calls) != 2 || calls[0].Step != 1 || calls[1].Step != 2 ||
		calls[0].Key() != "read_file {\"a\":1,\"z\":0}" || calls[1].Key() != calls[0].Key() {
		t.Fatalf("identity calls = (%#v, %v)", calls, err)
	}
	base := trace.Call{Tool: "tool", Args: "{}", OK: true, Tokens: 1}
	for _, tc := range []struct {
		name string
		call trace.Call
		same bool
	}{
		{name: "same", call: base, same: true},
		{name: "tool differs", call: trace.Call{Tool: "other", Args: "{}", OK: true, Tokens: 1}},
		{name: "args differ", call: trace.Call{Tool: "tool", Args: "{\"x\":1}", OK: true, Tokens: 1}},
		{name: "OK differs", call: trace.Call{Tool: "tool", Args: "{}", OK: false, Tokens: 1}, same: true},
		{name: "tokens differ", call: trace.Call{Tool: "tool", Args: "{}", OK: true, Tokens: 2}, same: true},
	} {
		if got := tc.call.Key() == base.Key(); got != tc.same {
			t.Errorf("%s: same key = %v, want %v", tc.name, got, tc.same)
		}
	}
}

func TestTraceAllOrNothing(t *testing.T) {
	calls, err := trace.Parse([]byte("{\"tool\":\"x\"}\n{"), "t.jsonl")
	if err == nil || err.Error() != "t.jsonl:2: invalid JSON" || calls != nil {
		t.Errorf("later failure = (%#v, %v)", calls, err)
	}
	calls, err = trace.Parse([]byte("{"), "<stdin>")
	if err == nil || err.Error() != "<stdin>:1: invalid JSON" || calls != nil {
		t.Errorf("stdin path = (%#v, %v)", calls, err)
	}
}

func TestTraceLongLiteralLine(t *testing.T) {
	const line = "{\"tool\":\"x\",\"args\":{\"payload\":\"" + "" + "\"}}"
	calls, err := trace.Parse([]byte(line), "t.jsonl")
	if err != nil || len(calls) != 1 || len(calls[0].Args) <= 65536 {
		t.Fatalf("long literal line: calls=%d err=%v", len(calls), err)
	}
}

func TestTraceByteHelper(t *testing.T) {
	if os.Getenv("TRAILSPIN_TRACE_BYTE_HELPER") == "" {
		return
	}
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(3)
	}
	calls, err := trace.Parse(data, "<stdin>")
	if err != nil {
		fmt.Fprintln(os.Stdout, err)
		os.Exit(2)
	}
	fmt.Fprintf(os.Stdout, "%d %s\n", len(calls), hex.EncodeToString(data))
	os.Exit(0)
}

func TestTraceRawByteInputProcess(t *testing.T) {
	for _, tc := range []struct {
		name     string
		data     []byte
		wantCode int
		wantOut  string
	}{
		{name: "invalid UTF-8", data: []byte{'{', 0xff, '}'}, wantCode: 2, wantOut: "<stdin>: input is not valid UTF-8\n"},
		{name: "BOM bytes", data: []byte{0xef, 0xbb, 0xbf, '{', '"', 't', 'o', 'o', 'l', '"', ':', '"', 'x', '"', '}'}, wantCode: 0, wantOut: "1 efbbbf7b22746f6f6c223a2278227d\n"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			defer cancel()
			cmd := exec.CommandContext(ctx, os.Args[0], "-test.run=^TestTraceByteHelper$")
			cmd.Env = append(os.Environ(), "TRAILSPIN_TRACE_BYTE_HELPER=1")
			cmd.Stdin = bytes.NewReader(tc.data)
			var stdout, stderr bytes.Buffer
			cmd.Stdout, cmd.Stderr = &stdout, &stderr
			err := cmd.Run()
			if ctx.Err() != nil {
				t.Fatalf("helper timed out: %v", ctx.Err())
			}
			code := 0
			if err != nil {
				var exit *exec.ExitError
				if !errors.As(err, &exit) {
					t.Fatalf("helper failed to start: %v", err)
				}
				code = exit.ExitCode()
			}
			if code != tc.wantCode || stdout.String() != tc.wantOut || stderr.Len() != 0 {
				t.Errorf("helper = (%d, %q, %q), want (%d, %q, empty stderr)", code, stdout.String(), stderr.String(), tc.wantCode, tc.wantOut)
			}
		})
	}
}
